Action.Str:
// Read request from intent extra
var requestJson = tasker.getIntent().getStringExtra("request_json");
if (!requestJson) {
  flash("No request_json in intent");
  stop();
}
var request = JSON.parse(requestJson);

// Store in local variables
setLocal("gw_version", request.version);
setLocal("gw_command_id", request.command_id);
setLocal("gw_adapter_id", request.adapter_id);
setLocal("gw_request_hash", request.request_hash);
setLocal("gw_issued_at_ms", request.issued_at_ms);
setLocal("gw_deadline_at_ms", request.deadline_at_ms);
setLocal("gw_nonce", request.nonce);
setLocal("gw_auth_sig", request.auth.signature);

// Invalid version — build error response
var resp = {
  version: 1,
  command_id: local("gw_command_id"),
  adapter_id: local("gw_adapter_id"),
  request_hash: local("gw_request_hash"),
  ok: false,
  status: "rejected",
  error: { code: "INVALID_VERSION", message: "Version must be 1" },
  auth: { algorithm: "HMAC-SHA256", signature: "" }
};
var gson = new com.google.gson.Gson();
var intent = new Intent("com.hermesandroid.bridge.TASKER_GATEWAY_RESPONSE_V1");
intent.setPackage("com.hermesandroid.bridge");
intent.putExtra("response_json", gson.toJson(resp));
context.sendBroadcast(intent);
stop();

// Check deadline
var now = java.lang.System.currentTimeMillis();
var deadline = parseInt(local("gw_deadline_at_ms"));
if (now > deadline) {
  var resp = {
    version: 1,
    command_id: local("gw_command_id"),
    adapter_id: local("gw_adapter_id"),
    request_hash: local("gw_request_hash"),
    ok: false,
    status: "rejected",
    error: { code: "deadline_exceeded", message: "Request expired before execution" },
    auth: { algorithm: "HMAC-SHA256", signature: "" }
  };
  var gson = new com.google.gson.Gson();
  var intent = new Intent("com.hermesandroid.bridge.TASKER_GATEWAY_RESPONSE_V1");
  intent.setPackage("com.hermesandroid.bridge");
  intent.putExtra("response_json", gson.toJson(resp));
  context.sendBroadcast(intent);
  stop();
}

// device_owner.status.v1 — STATIC adapter
var startTime = java.lang.System.currentTimeMillis();
var pkg = "net.dinglisch.android.taskerm";
var receiver = pkg + ".MyDeviceAdminReceiver";
var dpm = context.getSystemService("device_policy");
var admin = new android.content.ComponentName(context, receiver);

var result = {
  is_device_owner: dpm.isDeviceOwnerApp(pkg),
  package_name: pkg,
  admin_receiver: receiver,
  admin_active: dpm.isAdminActive(admin),
  device_model: android.os.Build.MODEL,
  android_version: "" + android.os.Build.VERSION.RELEASE,
  sdk_version: android.os.Build.VERSION.SDK_INT,
  kernel_version: java.lang.System.getProperty("os.version")
};

var completedAt = java.lang.System.currentTimeMillis();
var resp = {
  version: 1,
  command_id: local("gw_command_id"),
  adapter_id: "device_owner.status.v1",
  request_hash: local("gw_request_hash"),
  ok: true,
  status: "completed",
  received_at_ms: parseInt(local("gw_issued_at_ms")),
  started_at_ms: startTime,
  completed_at_ms: completedAt,
  duration_ms: completedAt - startTime,
  result: result,
  executor: {
    type: "tasker",
    package_name: pkg,
    process_uid: android.os.Process.myUid(),
    process_pid: android.os.Process.myPid(),
    task_name: "Hermes · Command Gateway"
  },
  error: null,
  auth: { algorithm: "HMAC-SHA256", signature: "" }
};

// Sign response (HMAC)
var respPayload = JSON.stringify(resp);
var key = tasker.getVariable("gw_secret");
var mac = javax.crypto.Mac.getInstance("HmacSHA256");
var secretBytes = new java.lang.String(key).getBytes("UTF-8");
var secretSpec = new javax.crypto.spec.SecretKeySpec(secretBytes, "HmacSHA256");
mac.init(secretSpec);
var sigBytes = mac.doFinal(respPayload.getBytes("UTF-8"));
var sig = android.util.Base64.encodeToString(sigBytes, android.util.Base64.NO_WRAP);
resp.auth.signature = sig;

// Send response back to Bridge
var gson = new com.google.gson.Gson();
var intent = new Intent("com.hermesandroid.bridge.TASKER_GATEWAY_RESPONSE_V1");
intent.setPackage("com.hermesandroid.bridge");
intent.putExtra("response_json", gson.toJson(resp));
context.sendBroadcast(intent);

// Unknown adapter — reject
var resp = {
  version: 1,
  command_id: local("gw_command_id"),
  adapter_id: local("gw_adapter_id"),
  request_hash: local("gw_request_hash"),
  ok: false,
  status: "rejected",
  error: { code: "UNKNOWN_ADAPTER", message: "Adapter not in allowlist: " + local("gw_adapter_id") },
  auth: { algorithm: "HMAC-SHA256", signature: "" }
};
var gson = new com.google.gson.Gson();
var intent = new Intent("com.hermesandroid.bridge.TASKER_GATEWAY_RESPONSE_V1");
intent.setPackage("com.hermesandroid.bridge");
intent.putExtra("response_json", gson.toJson(resp));
context.sendBroadcast(intent);
